-- Railway Database Dump for Fantrax Value Hunter
-- Import this into Railway PostgreSQL

BEGIN;

-- Table: players
CREATE TABLE IF NOT EXISTS players (
    id VARCHAR(10) NOT NULL,
    name VARCHAR(100) NOT NULL,
    team VARCHAR(5),
    position VARCHAR(10),
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    minutes INTEGER DEFAULT 0,
    xg90 DECIMAL(5,3) DEFAULT 0.000,
    xa90 DECIMAL(5,3) DEFAULT 0.000,
    xgi90 DECIMAL(5,3) DEFAULT 0.000,
    last_understat_update TIMESTAMP,
    true_value DECIMAL(8,2),
    roi DECIMAL(8,3),
    formula_version VARCHAR(10) DEFAULT 'v2.0'::character varying,
    exponential_form_score DECIMAL(5,3),
    baseline_xgi DECIMAL(5,3),
    blended_ppg DECIMAL(5,2),
    current_season_weight DECIMAL(4,3),
    games_current_season INTEGER DEFAULT 0
);

-- Data for players (15 batches)















-- Table: player_metrics
CREATE TABLE IF NOT EXISTS player_metrics (
    player_id VARCHAR(10) NOT NULL,
    gameweek INTEGER NOT NULL,
    price DECIMAL(6,2),
    ppg DECIMAL(6,2),
    ppg_source VARCHAR(20),
    value_score DECIMAL(8,3),
    true_value DECIMAL(8,3),
    form_multiplier DECIMAL(4,3) DEFAULT 1.0,
    fixture_multiplier DECIMAL(4,3) DEFAULT 1.0,
    starter_multiplier DECIMAL(4,3) DEFAULT 1.0,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    xgi_multiplier DECIMAL(5,3) DEFAULT 1.000,
    games_current_season INTEGER DEFAULT 0,
    imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Data for player_metrics (15 batches)















-- Table: player_games_data
CREATE TABLE IF NOT EXISTS player_games_data (
    player_id VARCHAR(50) NOT NULL,
    gameweek INTEGER NOT NULL,
    total_points DECIMAL(8,2) DEFAULT 0,
    games_played INTEGER DEFAULT 0,
    total_points_historical DECIMAL(8,2) DEFAULT 0,
    games_played_historical INTEGER DEFAULT 0,
    data_source VARCHAR(20) DEFAULT 'current'::character varying,
    last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Data for player_games_data (40 batches)








































-- Table: team_fixtures
CREATE TABLE IF NOT EXISTS team_fixtures (
    gameweek INTEGER NOT NULL,
    team_code VARCHAR(5) NOT NULL,
    opponent_code VARCHAR(5) NOT NULL,
    is_home BOOLEAN NOT NULL,
    difficulty_score DECIMAL(3,1) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    imported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Data for team_fixtures (1 batches)

-- Table: name_mappings
CREATE TABLE IF NOT EXISTS name_mappings (
    id INTEGER NOT NULL,
    source_system VARCHAR(50) NOT NULL,
    source_name VARCHAR(255) NOT NULL,
    fantrax_id VARCHAR(50) NOT NULL,
    fantrax_name VARCHAR(255),
    team VARCHAR(10),
    position VARCHAR(10),
    confidence_score DOUBLE PRECISION DEFAULT 0,
    match_type VARCHAR(50),
    verified BOOLEAN DEFAULT false,
    verification_date TIMESTAMP,
    verified_by VARCHAR(100),
    last_used TIMESTAMP,
    usage_count INTEGER DEFAULT 0,
    notes TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Data for name_mappings (29 batches)





























COMMIT;

-- Verification
SELECT 'Import completed!' as status;
SELECT COUNT(*) as total_players FROM players;
SELECT COUNT(*) as total_metrics FROM player_metrics;
